using System.Net;using System.Text.Json;namespace QuanLyKho.Middleware;public sealed class ExceptionHandlingMiddleware{readonly RequestDelegate next;readonly ILogger<ExceptionHandlingMiddleware> log;public ExceptionHandlingMiddleware(RequestDelegate next,ILogger<ExceptionHandlingMiddleware> log){this.next=next;this.log=log;}public async Task InvokeAsync(HttpContext c){try{await next(c);}catch(KeyNotFoundException e){await Error(c,HttpStatusCode.NotFound,e.Message);}catch(UnauthorizedAccessException e){await Error(c,HttpStatusCode.Forbidden,e.Message);}catch(ArgumentException e){await Error(c,HttpStatusCode.BadRequest,e.Message);}catch(InvalidOperationException e){await Error(c,HttpStatusCode.BadRequest,e.Message);}catch(Exception e){log.LogError(e,"Unhandled API exception");await Error(c,HttpStatusCode.InternalServerError,"Đã xảy ra lỗi không mong muốn.");}}static async Task Error(HttpContext c,HttpStatusCode s,string m){if(c.Response.HasStarted)return;c.Response.StatusCode=(int)s;c.Response.ContentType="application/json; charset=utf-8";await c.Response.WriteAsync(JsonSerializer.Serialize(new{success=false,message=m}));}}